WITH recent_customers AS (SELECT *, UPPER(email) AS email_upper FROM customers WHERE city IN ('Tokyo', 'New York')), customers_stats AS (SELECT QUARTER(signup_date) AS signup_quarter, DATE_FORMAT(signup_date, 'yyyy-MM') AS signup_month, SUM(CASE WHEN segment = 'Corporate' THEN credit_limit ELSE 0 END) AS corporate_credit_limit FROM recent_customers GROUP BY QUARTER(signup_date), DATE_FORMAT(signup_date, 'yyyy-MM')) SELECT signup_quarter, signup_month, corporate_credit_limit FROM customers_stats WHERE corporate_credit_limit >= 46 ORDER BY signup_quarter DESC, signup_month ASC LIMIT 20;
